using System;

namespace StdbModule;

public static partial class SwedishQuotes
{
    public static class SelmaLagerlöf
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "En sträng och dugande fru är hon, majorskan på Ekeby. Hon lyfter en tunna råg på sina breda skuldror. Hon följer malmforan, hämtad i Bergslagens gruvfält, på den långa vägen till Ekeby. Hon sover som en forbonde på ladans golv med en säck till huvudgärd. Om vintern kan hon vakta en kolmila, om sommaren följa en timmerflotte utför Löven. En myndig fru är hon. Hon svär som en gatpojke och regerar som en kung sina sju bruk och sina grannars gårdar, regerar sin egen socken och grannsocknarna, ja hela det sköna Värmland. Men för hemlösa kavaljerer har hon varit som en mor, och därför ha de hållit sina öron stängda, då förtalet viskat till dem, att hon står i förbund med djävulen.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Ack, Värmland, sade han, du sköna, du härliga! Ofta, när jag har sett dig framför mig på en karta, har jag undrat vad du månde föreställa, men nu förstår jag vad du är. Du är en gammal from eremit, som sitter stilla och drömmer med korslagda ben och händerna vilande i skötet. Du har en spetsig mössa nerdragen mot dina halvslutna ögon. Du är en grubblare, en helig drömmare, och du är mycket skön. Vida skogar är din klädnad. Långa band av blått vatten och jämnlöpande räckor av blåa kullar kantar den. Du är så enkel, att främlingen inte ser hur skön du är. Du är fattig, såsom de fromma åstundar att vara. Du sitter stilla, medan Vänerns böljor sköljer dina fötter och dina korslagda ben. Till vänster har du dina malmfält och gruvor. Där är ditt klappande hjärta. Åt norr har du ödslighetens, hemlighetens mörka, sköna trakter. Där är ditt drömmande huvud.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Där stod han nu och höll mellan sina händer någonting, som var varmt och mjukt och inrullat i en stor schal. Schalen var så pass undanviken, att han såg det lilla rynkiga ansiktet och de små vissna händerna. Han stod och undrade vad kvinnfolken menade att han skulle ta sig till med det här, som barnmorskan lagt i famnen på honom, då han fick en stöt, så att både han och barnet skakade till. Den kom inte från någon av de andra, men om den gick från den lilla flickan över till honom eller från honom till den lilla flickan, det kunde han inte reda ut för sig.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Strax efteråt började hjärtat klappa i bröstet på honom, såsom det aldrig förr hade gjort, och med detsamma var han inte längre frusen, och inte kände han sig ledsen och bekymrad, och inte ond heller, utan allt var bra. Det enda, som oroade honom, var, att han inte kunde begripa varför det skulle dunka och slå på det sättet i bröstet på honom, då han varken hade dansat eller sprungit eller klättrat i branta berg.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Nu kom Klara Gulla på det! Hon förstod, att skollärarn ville, att de skulle svara, att de kallade Gud för fader, och så sträckte hon upp handen.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Vad kalla vi Gud för, Klara Gulla? sa skollärarn.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Klara Gulla reste sig upp i bänken med högt blossande kinder och den lilla snärten till fläta bak i nacken stående rätt ut.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Vi kallar honom Jan, svarade hon med hög och tydlig röst.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Och med detsamma gick det ett litet fnissande genom hela skolhuset. Herrskaper och skolrådsledamöter och föräldrar och skolbarn, alla drog de litet på munnen, och till och med skollärarn såg road ut.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Det är gott, så länge som en kan göra sej kalas i tankarna, sa notbindaren urskuldande. Di smakar bättre di än di riktiga.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Det skulle smaka mig bättre än vetebröd te kaffe, om jag fick höra Klara Gullas brev, medan jag sitter här å röker, sa Jan.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "Kära älskade.", Author = "Selma Lagerlöf" },
            new Quote { Id = "https://sv.wikiquote.org/wiki/Selma_Lagerlöf", Text = "I dag har jag kommit hit till Narvik och funnit ditt bref till Falun och ditt sist skrifna samt ett telegram. Mycket tack. Du skall inte vara rädd, jag glömmer dig inte. Det finns ingen anledning. Det andra ger ingen trygghet, men nu är jag glad, då omkastningarna äro för stora, att tänka på dig, som är trygghet och trofasthet. Du får lof att alltid vara mig trogen du får aldrig bli ond på mig och aldrig tvifla på mig och framför allt får du inte flytta ifrån mig. Jag är viss om att häri ligger både din lycka och min. Jag tycker ju förstås, att jag är förfärligt egoistisk, som vill ha dig helt för mig, men jag tror, att det är vår lycka det gäller.", Author = "Selma Lagerlöf" },
        };
    }
}